parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "exactitud_factual": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5,
      "description": "Precisión factual del borrador contra la evidencia del manual (1 a 5)"
    },
    "estado_veredicto": {
      "type": "string",
      "enum": [
        "ACEPTADO",
        "CORREGIR",
        "RECHAZADO"
      ],
      "description": "Ruta que debe tomar el borrador"
    },
    "categoria_error": {
      "type": "string",
      "enum": [
        "ninguno",
        "precio_incorrecto",
        "plazo_incorrecto",
        "dato_inventado",
        "regla_no_se_mal_aplicada",
        "consulta_no_respondida",
        "sin_fuente",
        "tono_inadecuado",
        "riesgo_politica"
      ],
      "description": "Causa principal del error"
    },
    "critica": {
      "type": "string",
      "maxLength": 400,
      "description": "Corrección accionable para el agente redactor"
    }
  },
  "required": [
    "exactitud_factual",
    "estado_veredicto",
    "categoria_error",
    "critica"
  ],
  "additionalProperties": false
}
